<template><div class="page"><h2 class="page-title">消费基线预测</h2><p class="muted">根据历史周消费估计“如果保持原有习惯，未来大约会花多少”，供预算方案比较使用。</p><el-alert title="这不是消费承诺。计划外大额支出、生活变化和分类不确定性都可能造成误差。" type="warning" :closable="false"/><div class="card section"><div class="actions"><el-select v-model="goalId" placeholder="选择储蓄目标"><el-option v-for="g in goals" :key="g.id" :label="`${formatMoney(g.target_savings_minor)}，截至 ${g.target_date}`" :value="g.id"/></el-select><el-button type="primary" :loading="loading" :disabled="!goalId" @click="load">查看消费基线</el-button></div><EChart v-if="totals.length" :option="chart"/><EmptyGuide v-else :description="goals.length?'请选择目标并查看消费基线':'还没有储蓄目标'" :hint="goals.length?'系统会根据目标剩余周期生成周度参考。':'先设置目标和预算底线。'" action="/goals" action-text="设置储蓄目标"/></div><div v-if="items.length" class="card section"><h3>分类参考</h3><el-alert title="购物数据波动较大，只能作为低可信度参考；分类预算仍以总消费和用户底线为主。" type="warning" :closable="false"/><el-table :data="references"><el-table-column label="类别"><template #default="s">{{categoryName(s.row.target_key)}}</template></el-table-column><el-table-column label="每周参考"><template #default="s">{{formatMoney(s.row.predicted_minor)}}</template></el-table-column><el-table-column label="可信程度"><template #default="s">{{s.row.target_key==='food'?'可参考':s.row.target_key==='shopping'?'较低，仅辅助':'历史结构参考'}}</template></el-table-column></el-table><el-collapse class="section"><el-collapse-item title="查看预测范围与方法说明"><p>折线两侧范围表示历史波动下的可能区间，不是成功概率。预算优化使用阶段 6 已选定方法，本页不会重新选择模型。</p></el-collapse-item></el-collapse><div class="next-step"><b>消费基线已准备好</b><el-button type="primary" @click="$router.push('/budgets')">生成预算方案</el-button></div></div></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js';import { categoryName } from '../utils/display.js';import EChart from '../components/EChart.vue';import EmptyGuide from '../components/EmptyGuide.vue'
const goals=ref([]),goalId=ref(),items=ref([]),loading=ref(false);onMounted(async()=>goals.value=(await api.get('/goals')).items);async function load(){loading.value=true;try{items.value=(await api.get(`/forecasts/weekly?goal_id=${goalId.value}`)).items}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}const totals=computed(()=>items.value.filter(x=>x.target_key==='total'));const references=computed(()=>{const first=new Map();items.value.filter(x=>x.target_key!=='total').forEach(x=>first.has(x.target_key)||first.set(x.target_key,x));return [...first.values()]});const chart=computed(()=>({tooltip:{trigger:'axis',valueFormatter:v=>formatMoney(v)},legend:{},xAxis:{type:'category',data:totals.value.map(x=>x.week_start)},yAxis:{type:'value'},series:[{name:'预计消费',type:'line',data:totals.value.map(x=>x.predicted_minor),color:'#2b9a72'},{name:'较低情形',type:'line',lineStyle:{type:'dashed'},data:totals.value.map(x=>x.lower_minor)},{name:'较高情形',type:'line',lineStyle:{type:'dashed'},data:totals.value.map(x=>x.upper_minor)}]}))
</script>
